import type { IGameDataProvider } from '../data/index.js';
import type { Board, Coord, MatchState, Tile } from '../model/index.js';
import { hasLineOfSight, tilesOnLine } from './line-of-sight.js';
import { coordKey } from './board.js';

// --- test doubles -----------------------------------------------------------

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: stubProvider — (no summary)
// @ai-hash: 0ecc9ac1
// ── END AI-METHOD ──
/** Provider stub: LoS only calls terrainEffect. Forest/Mountain block sight. */
function stubProvider(): IGameDataProvider {
  return {
    terrainEffect: (key: string) => ({
      terrainKey: key,
      moveCost: 1,
      passable: { ground: true, flying: true, aquatic: true },
      cover: key === 'Forest' ? 2 : 0,
      blocksLoS: key === 'Forest' || key === 'Mountain',
    }),
  } as unknown as IGameDataProvider;
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: board — (no summary)
// @ai-hash: 0c626664
// ── END AI-METHOD ──
function board(w: number, h: number, terrainAt?: (c: Coord) => string): Board {
  const tiles: Tile[][] = [];
  for (let y = 0; y < h; y++) {
    const row: Tile[] = [];
    for (let x = 0; x < w; x++) row.push({ terrain: terrainAt?.({ x, y }) ?? 'Field', feature: null });
    tiles.push(row);
  }
  return { width: w, height: h, tiles };
}

// ── AI-METHOD ── regenerated by annotate_methods — do not hand-edit
// @ai-method: state — (no summary)
// @ai-hash: 37a9e919
// ── END AI-METHOD ──
function state(b: Board): MatchState {
  return {
    modeId: 'skirmish',
    board: b,
    armies: [],
    tokens: [],
    turn: 1,
    activeSide: 0,
    moon: { gameHour: 0, sky: { Black: 'FullMoon', Red: 'FullMoon', White: 'FullMoon' } },
    rngState: 1,
    status: 'in-progress',
  };
}

// --- tests ------------------------------------------------------------------

describe('tilesOnLine', () => {
  it('traces a horizontal line inclusive of both endpoints', () => {
    expect(tilesOnLine({ x: 0, y: 0 }, { x: 3, y: 0 }).map(coordKey)).toEqual(['0,0', '1,0', '2,0', '3,0']);
  });
  it('traces a diagonal line', () => {
    expect(tilesOnLine({ x: 0, y: 0 }, { x: 2, y: 2 }).map(coordKey)).toEqual(['0,0', '1,1', '2,2']);
  });
  it('traces a vertical line', () => {
    expect(tilesOnLine({ x: 0, y: 0 }, { x: 0, y: 3 }).map(coordKey)).toEqual(['0,0', '0,1', '0,2', '0,3']);
  });
});

describe('hasLineOfSight', () => {
  const p = stubProvider();

  it('adjacent tiles always see each other', () => {
    expect(hasLineOfSight(state(board(5, 5)), { x: 0, y: 0 }, { x: 1, y: 0 }, p)).toBe(true);
  });

  it('clear terrain gives line of sight', () => {
    expect(hasLineOfSight(state(board(10, 10)), { x: 0, y: 0 }, { x: 5, y: 5 }, p)).toBe(true);
  });

  it('a forest on the line blocks sight', () => {
    const b = board(10, 10, (c) => (c.x === 3 && c.y === 3 ? 'Forest' : 'Field'));
    expect(hasLineOfSight(state(b), { x: 0, y: 0 }, { x: 5, y: 5 }, p)).toBe(false);
  });

  it('a mountain on the line blocks sight', () => {
    const b = board(10, 10, (c) => (c.x === 2 && c.y === 2 ? 'Mountain' : 'Field'));
    expect(hasLineOfSight(state(b), { x: 0, y: 0 }, { x: 5, y: 5 }, p)).toBe(false);
  });

  it('blocking terrain at an endpoint is ignored', () => {
    const b = board(10, 10, (c) =>
      (c.x === 0 && c.y === 0) || (c.x === 5 && c.y === 5) ? 'Forest' : 'Field',
    );
    expect(hasLineOfSight(state(b), { x: 0, y: 0 }, { x: 5, y: 5 }, p)).toBe(true);
  });
});
